const tomb=id=>{try{const a=JSON.parse(localStorage.getItem('sizeup_del')||'[]');a.push(id);localStorage.setItem('sizeup_del',JSON.stringify(a.slice(-500)))}catch(e){}};
function bindJrn(){
  let L=[];try{L=JSON.parse(localStorage.getItem('sizeup_j')||'[]')}catch(e){}
  const sv=()=>{try{localStorage.setItem('sizeup_j',JSON.stringify(L))}catch(e){}window.syncPush&&window.syncPush()},sum=a=>a.reduce((s,x)=>s+x.p,0);
  const draw=()=>{
    const w=L.filter(x=>x.p>0),l=L.filter(x=>x.p<0),tot=sum(L),gl=-sum(l),rs=L.filter(x=>x.r>0);
    $('gres').innerHTML=L.length?[['Trades',L.length],['Win rate',f(w.length/L.length*100)+'%'],['Total P&L',usd(tot)],['Expectancy per trade',usd(tot/L.length)],['Profit factor',gl?f(sum(w)/gl):'-'],['Average R',rs.length?f(rs.reduce((s,x)=>s+x.p/x.r,0)/rs.length)+' R':'-']].map(stat).join(''):stat(['Stats','Log your first trade above']);
    let c=0;const pts=[0].concat(L.map(x=>c+=x.p)),hi=Math.max(...pts,0),lo=Math.min(...pts,0),X=i=>(i/Math.max(1,pts.length-1)*400).toFixed(1),Y=y=>(154-(y-lo)/(hi-lo||1)*148).toFixed(1);
    $('chart').innerHTML=L.length>1?'<line x1="0" x2="400" y1="'+Y(0)+'" y2="'+Y(0)+'" style="stroke:var(--mut)" stroke-dasharray="4"/><polyline fill="none" stroke-width="2.5" style="stroke:var(--acc)" points="'+pts.map((y,i)=>X(i)+','+Y(y)).join(' ')+'"/>':'';
    $('jl').innerHTML=L.slice(-8).reverse().map((x,k)=>'<div class="jr"><span>'+x.d+' '+x.s+'</span><b class="'+(x.p>=0?'pos':'neg')+'">'+usd(x.p)+'</b><button data-i="'+(L.length-1-k)+'" aria-label="Delete trade">✕</button></div>').join('')||'<p class="hint">No trades yet.</p>';
  };
  $('jl').addEventListener('click',e=>{const i=e.target.dataset.i;if(i===undefined)return;const d=L.splice(+i,1)[0];if(d&&d.id)tomb(d.id);sv();draw()});
  $('add').addEventListener('click',()=>{
    const p=parseFloat($('jp').value);
    if(!Number.isFinite(p)||p===0){$('toast').textContent='Enter a profit or a loss (a loss is negative).';return}
    L.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,6),d:new Date().toLocaleDateString(undefined,{month:'short',day:'numeric'}),s:$('js').value.toUpperCase().replace(/[^A-Z0-9._ -]/g,'')||'-',p,r:Math.abs(parseFloat($('jr').value))||0});
    if(L.length>500)L.shift();
    let m='Trade logged.';
    if(S.jd!==today()){S.jd=today();S.jc=0}
    if(S.jc<3){S.jc++;S.xp+=5;m+=' +5 XP for journaling.'}
    if(S.last!==today()){const y=new Date(Date.now()-864e5).toDateString();S.streak=S.last===y?S.streak+1:1;S.last=today()}
    if(L.length>=5&&!S.badges.includes('journal')){S.badges.push('journal');m+=' New badge: Journaled 5 trades.'}
    sv();save();chips();draw();$('js').value=$('jp').value=$('jr').value='';$('toast').textContent=m;
  });
  draw();
}
