const rd=k=>{try{return JSON.parse(localStorage.getItem(k)||'null')}catch(e){return null}};
const snap=()=>({s:S,j:rd('sizeup_j')||[],del:rd('sizeup_del')||[]});
const cj=o=>JSON.stringify(o,(k,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.entries(v).sort()):v);
const idOf=x=>x.id||JSON.stringify(x);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function merge(a,b){
  const del=[...new Set([...(a.del||[]),...(b.del||[])])],seen={},j=[];
  [...(a.j||[]),...(b.j||[])].forEach(x=>{const k=idOf(x);if(!seen[k]&&!del.includes(k)){seen[k]=1;j.push(x)}});
  j.sort((x,y)=>(x.id||'')<(y.id||'')?-1:(x.id||'')>(y.id||'')?1:0);
  const sa=a.s||{},sb=b.s||{},later=sa.last&&(!sb.last||new Date(sa.last)>=new Date(sb.last))?sa:sb;
  const s=Object.assign({},later,{xp:Math.max(sa.xp||0,sb.xp||0),plans:Math.max(sa.plans||0,sb.plans||0),badges:[...new Set([...(sa.badges||[]),...(sb.badges||[])])]});
  return{s,j,del:del.slice(-500)};
}
